import { readFileSync, writeFileSync } from 'node:fs'
import { dirname, resolve } from 'node:path'
import { fileURLToPath } from 'node:url'

const root = resolve(dirname(fileURLToPath(import.meta.url)), '..')
const target = resolve(root, 'src/lib/backend-mark-assets.ts')
const sources = Object.fromEntries(['claude', 'codex', 'gemini'].map(backend => [backend, {
  uri: `data:image/${backend === 'gemini' ? 'svg+xml' : 'png'};base64,${readFileSync(resolve(root, `assets/backend-${backend}.${backend === 'gemini' ? 'svg' : 'png'}`)).toString('base64')}`,
}]))
const output = [
  '// Generated by scripts/embed-backend-marks.mjs. Do not edit by hand.',
  '// Keep these small marks independent of Metro and server connectivity.',
  `export const BACKEND_MARK_SOURCES = ${JSON.stringify(sources, null, 2)} as const`,
  '',
].join('\n')
if (process.argv.includes('--check')) {
  if (readFileSync(target, 'utf8') !== output) throw new Error('Run scripts/embed-backend-marks.mjs to refresh embedded marks.')
} else {
  writeFileSync(target, output)
}
